2106|bool ucl_parser_set_filevars(struct ucl_parser *parser, const char *filename, bool need_expand)
2107|{
2108|	char realbuf[PATH_MAX], *curdir;
2109|
2110|	if (filename != NULL) {
2111|		if (need_expand) {
2112|			if (ucl_realpath(filename, realbuf) == NULL) {
2113|				return false;
2114|			}
2115|		}
2116|		else {
2117|			ucl_strlcpy(realbuf, filename, sizeof(realbuf));
2118|		}
2119|
2120|		if (parser->cur_file) {
2121|			UCL_FREE(strlen(parser->cur_file) + 1, parser->cur_file);
2122|		}
2123|
2124|		parser->cur_file = UCL_STRDUP(realbuf);
2125|
2126|		/* Define variables */
2127|		ucl_parser_register_variable(parser, "FILENAME", realbuf);
2128|		curdir = dirname(realbuf);
2129|		ucl_parser_register_variable(parser, "CURDIR", curdir);
2130|	}
