728|void ucl_parser_free(struct ucl_parser *parser)
729|{
730|	struct ucl_stack *stack, *stmp;
731|	struct ucl_macro *macro, *mtmp;
732|	struct ucl_chunk *chunk, *ctmp;
733|	struct ucl_pubkey *key, *ktmp;
734|	struct ucl_variable *var, *vtmp;
735|	ucl_object_t *tr, *trtmp;
736|
737|	if (parser == NULL) {
738|		return;
739|	}
740|
741|	if (parser->top_obj != NULL) {
742|		ucl_object_unref(parser->top_obj);
743|	}
744|
745|	if (parser->includepaths != NULL) {
746|		ucl_object_unref(parser->includepaths);
747|	}
748|
749|	LL_FOREACH_SAFE(parser->stack, stack, stmp)
750|	{
751|		UCL_FREE(sizeof(struct ucl_stack), stack);
752|	}
753|	HASH_ITER(hh, parser->macroes, macro, mtmp)
754|	{
755|		UCL_FREE(strlen(macro->name) + 1, macro->name);
756|		HASH_DEL(parser->macroes, macro);
757|		UCL_FREE(sizeof(struct ucl_macro), macro);
758|	}
759|	LL_FOREACH_SAFE(parser->chunks, chunk, ctmp)
760|	{
761|		ucl_chunk_free(chunk);
762|	}
763|	LL_FOREACH_SAFE(parser->keys, key, ktmp)
764|	{
765|		UCL_FREE(sizeof(struct ucl_pubkey), key);
766|	}
767|	LL_FOREACH_SAFE(parser->variables, var, vtmp)
768|	{
769|		UCL_FREE(var->value_len + 1, var->value);
770|		UCL_FREE(var->var_len + 1, var->var);
771|		UCL_FREE(sizeof(struct ucl_variable), var);
772|	}
773|	LL_FOREACH_SAFE(parser->trash_objs, tr, trtmp)
774|	{
775|		ucl_object_free_shallow(tr);
776|	}
777|
778|	if (parser->err != NULL) {
779|		utstring_free(parser->err);
780|	}
781|
782|	if (parser->cur_file) {
783|		UCL_FREE(strlen(parser->cur_file) + 1, parser->cur_file);
784|	}
785|
786|	if (parser->comments) {
787|		ucl_object_unref(parser->comments);
788|	}
789|
790|	UCL_FREE(sizeof(struct ucl_parser), parser);
791|}

