426|size_t
427|ucl_unescape_json_string(char *str, size_t len)
428|{
429|	char *t = str, *h = str;
430|	int i, uval;
431|
432|	if (len <= 1) {
433|		return len;
434|	}
435|	/* t is target (tortoise), h is source (hare) */
436|
437|	while (len) {
438|		if (*h == '\\') {
439|			h++;
440|
441|			if (len == 1) {
442|				/*
443|				 * If \ is last, then do not try to go further
444|				 * Issue: #74
445|				 */
446|				len--;
447|				*t++ = '\\';
448|				continue;
449|			}
450|
451|			switch (*h) {
452|			case 'n':
453|				*t++ = '\n';
454|				break;
455|			case 'r':
456|				*t++ = '\r';
457|				break;
458|			case 'b':
459|				*t++ = '\b';
460|				break;
461|			case 't':
462|				*t++ = '\t';
463|				break;
464|			case 'f':
465|				*t++ = '\f';
466|				break;
467|			case '\\':
468|				*t++ = '\\';
469|				break;
470|			case '"':
471|				*t++ = '"';
472|				break;
473|			case 'u':
474|				/* Unicode escape */
475|				uval = 0;
476|				h++; /* u character */
477|				len--;
478|
479|				if (len > 3) {
480|					for (i = 0; i < 4; i++) {
481|						uval <<= 4;
482|						if (isdigit(h[i])) {
483|							uval += h[i] - '0';
484|						}
485|						else if (h[i] >= 'a' && h[i] <= 'f') {
486|							uval += h[i] - 'a' + 10;
487|						}
488|						else if (h[i] >= 'A' && h[i] <= 'F') {
489|							uval += h[i] - 'A' + 10;
490|						}
491|						else {
492|							break;
493|						}
494|					}
495|
496|					/* Encode */
497|					if (uval < 0x80) {
498|						t[0] = (char) uval;
499|						t++;
500|					}
501|					else if (uval < 0x800) {
502|						t[0] = 0xC0 + ((uval & 0x7C0) >> 6);
503|						t[1] = 0x80 + ((uval & 0x03F));
504|						t += 2;
505|					}
506|					else if (uval < 0x10000) {
507|						t[0] = 0xE0 + ((uval & 0xF000) >> 12);
508|						t[1] = 0x80 + ((uval & 0x0FC0) >> 6);
509|						t[2] = 0x80 + ((uval & 0x003F));
510|						t += 3;
511|					}
512|#if 0
513|					/* It's not actually supported now */
514|					else if(uval <= 0x10FFFF) {
515|						t[0] = 0xF0 + ((uval & 0x1C0000) >> 18);
516|						t[1] = 0x80 + ((uval & 0x03F000) >> 12);
517|						t[2] = 0x80 + ((uval & 0x000FC0) >> 6);
518|						t[3] = 0x80 + ((uval & 0x00003F));
519|						t += 4;
520|					}
521|#endif
522|					else {
523|						*t++ = '?';
524|					}
525|
526|					/* Consume 4 characters of source */
527|					h += 4;
528|					len -= 4;
529|
530|					if (len > 0) {
531|						len--; /* for '\' character */
532|					}
533|					continue;
534|				}
535|				else {
536|					*t++ = 'u';
537|				}
538|				break;
539|			default:
540|				*t++ = *h;
541|				break;
542|			}
543|			h++;
544|			len--;
545|		}
546|		else {
547|			*t++ = *h++;
548|		}
549|
550|		if (len > 0) {
551|			len--;
552|		}
553|	}
554|	*t = '\0';
555|
556|	return (t - str);
557|}
