559|size_t
560|ucl_unescape_squoted_string(char *str, size_t len)
561|{
562|	char *t = str, *h = str;
563|
564|	if (len <= 1) {
565|		return len;
566|	}
567|
568|	/* t is target (tortoise), h is source (hare) */
569|
570|	while (len) {
571|		if (*h == '\\') {
572|			h++;
573|
574|			if (len == 1) {
575|				/*
576|				 * If \ is last, then do not try to go further
577|				 * Issue: #74
578|				 */
579|				len--;
580|				*t++ = '\\';
581|				continue;
582|			}
583|
584|			switch (*h) {
585|			case '\'':
586|				*t++ = '\'';
587|				break;
588|			case '\n':
589|				/* Ignore \<newline> style stuff */
590|				break;
591|			case '\r':
592|				/* Ignore \r and the following \n if needed */
593|				if (len > 1 && h[1] == '\n') {
594|					h++;
595|					len--;
596|				}
597|				break;
598|			default:
599|				/* Ignore \ */
600|				*t++ = '\\';
601|				*t++ = *h;
602|				break;
603|			}
604|
605|			h++;
606|			len--;
607|		}
608|		else {
609|			*t++ = *h++;
610|		}
611|
612|		if (len > 0) {
613|			len--;
614|		}
615|	}
616|
617|	*t = '\0';
618|
619|	return (t - str);
620|}
