1550|/**
1551| * Include a file to configuration
1552| * @param data
1553| * @param len
1554| * @param parser
1555| * @param err
1556| * @return
1557| */
1558|static bool
1559|ucl_include_file(const unsigned char *data, size_t len,
1560|				 struct ucl_parser *parser,
1561|				 struct ucl_include_params *params,
1562|				 const ucl_object_t *args)
1563|{
1564|	const unsigned char *p = data, *end = data + len;
1565|	bool need_glob = false;
1566|	int cnt = 0;
1567|	char glob_pattern[PATH_MAX];
1568|	size_t i;
1569|
1570|#ifndef _WIN32
1571|	if (!params->allow_glob) {
1572|		return ucl_include_file_single(data, len, parser, params);
1573|	}
1574|	else {
1575|		/* Check for special symbols in a filename */
1576|		while (p != end) {
1577|			if (*p == '*' || *p == '?') {
1578|				need_glob = true;
1579|				break;
1580|			}
1581|			p++;
1582|		}
1583|		if (need_glob) {
1584|			glob_t globbuf;
1585|			memset(&globbuf, 0, sizeof(globbuf));
1586|			ucl_strlcpy(glob_pattern, (const char *) data,
1587|						(len + 1 < sizeof(glob_pattern) ? len + 1 : sizeof(glob_pattern)));
1588|			if (glob(glob_pattern, 0, NULL, &globbuf) != 0) {
1589|				return (!params->must_exist || false);
1590|			}
1591|			for (i = 0; i < globbuf.gl_pathc; i++) {
1592|
1593|				if (parser->include_trace_func) {
1594|					const ucl_object_t *parent = NULL;
1595|
1596|					if (parser->stack) {
1597|						parent = parser->stack->obj;
1598|					}
1599|
1600|					parser->include_trace_func(parser, parent, NULL,
1601|											   globbuf.gl_pathv[i],
1602|											   strlen(globbuf.gl_pathv[i]),
1603|											   parser->include_trace_ud);
1604|				}
1605|
1606|				if (!ucl_include_file_single((unsigned char *) globbuf.gl_pathv[i],
1607|											 strlen(globbuf.gl_pathv[i]), parser, params)) {
1608|					if (params->soft_fail) {
1609|						continue;
1610|					}
1611|					globfree(&globbuf);
1612|					return false;
1613|				}
1614|				cnt++;
1615|			}
1616|			globfree(&globbuf);
1617|
1618|			if (cnt == 0 && params->must_exist) {
1619|				ucl_create_err(&parser->err, "cannot match any files for pattern %s",
1620|							   glob_pattern);
1621|				return false;
1622|			}
1623|		}
1624|		else {
1625|			return ucl_include_file_single(data, len, parser, params);
1626|		}
1627|	}
1628|#else
1629|	/* Win32 compilers do not support globbing. Therefore, for Win32,
1630|	   treat allow_glob/need_glob as a NOOP and just return */
1631|	return ucl_include_file_single(data, len, parser, params);
1632|#endif
1633|
1634|	return true;
