3900|		break;
3901|	case UCL_ARRAY:
3902|		if (o1->len == o2->len && o1->len > 0) {
3903|			UCL_ARRAY_GET(vec1, o1);
3904|			UCL_ARRAY_GET(vec2, o2);
3905|			unsigned i;
3906|
3907|			/* Compare all elements in both arrays */
3908|			for (i = 0; i < vec1->n; i++) {
3909|				it1 = kv_A(*vec1, i);
3910|				it2 = kv_A(*vec2, i);
3911|
3912|				if (it1 == NULL && it2 != NULL) {
3913|					return -1;
3914|				}
3915|				else if (it2 == NULL && it1 != NULL) {
3916|					return 1;
3917|				}
3918|				else if (it1 != NULL && it2 != NULL) {
3919|					ret = ucl_object_compare(it1, it2);
3920|					if (ret != 0) {
3921|						break;
3922|					}
3923|				}
3924|			}
3925|		}
3926|		else {
3927|			ret = o1->len - o2->len;
3928|		}
3929|		break;
3930|	case UCL_OBJECT:
