3938|				ret = ucl_object_compare(it1, it2);
3939|				if (ret != 0) {
3940|					break;
3941|				}
3942|			}
3943|		}
3944|		else {
3945|			ret = o1->len - o2->len;
3946|		}
3947|		break;
3948|	default:
3949|		ret = 0;
3950|		break;
3951|	}
3952|
3953|	return ret;
