197|static void
198|ucl_object_dtor_free(ucl_object_t *obj)
199|{
200|	if (obj->trash_stack[UCL_TRASH_KEY] != NULL) {
201|		UCL_FREE(obj->hh.keylen, obj->trash_stack[UCL_TRASH_KEY]);
202|	}
