204|		UCL_FREE(obj->len, obj->trash_stack[UCL_TRASH_VALUE]);
205|	}
206|	/* Do not free ephemeral objects */
207|	if ((obj->flags & UCL_OBJECT_EPHEMERAL) == 0) {
208|		if (obj->type != UCL_USERDATA) {
209|			UCL_FREE(sizeof(ucl_object_t), obj);
210|		}
211|		else {
