221|/*
222| * Destroying a UCL tree is a graph traversal: releasing a container releases
223| * its children, which may be containers themselves. Doing that on the C stack
224| * makes cleanup depth proportional to the nesting depth of the document, so a
225| * deeply nested (and possibly attacker supplied) input could exhaust the stack
226| * while being freed - long after the parser had returned successfully.
227| *
228| * So the traversal is explicit instead. An object only reaches the worklist
229| * once its last reference is gone, which means it is already detached from the
230| * tree and nothing else can observe it; its `next` pointer is therefore free
231| * for us to reuse as the worklist link. That keeps destruction allocation free
232| * and its stack usage constant.
233| */
234|struct ucl_dtor_worklist {
235|	ucl_object_t *head;
236|};
237|
238|static inline void
239|ucl_dtor_worklist_push(struct ucl_dtor_worklist *wl, ucl_object_t *obj)
240|{
241|	obj->next = wl->head;
242|	wl->head = obj;
243|}
244|
245|static inline ucl_object_t *
246|ucl_dtor_worklist_pop(struct ucl_dtor_worklist *wl)
247|{
248|	ucl_object_t *obj = wl->head;
249|
250|	if (obj != NULL) {
251|		wl->head = obj->next;
252|		obj->next = NULL;
253|	}
254|
255|	return obj;
256|}
257|
258|/*
259| * Drop one reference to `obj` and queue it for destruction if that was the
260| * last one. `obj` must already be unlinked from whatever contained it.
261| */
262|static void
263|ucl_dtor_worklist_unref(void *ptr, void *ud)
264|{
265|	ucl_object_t *obj = (ucl_object_t *) ptr;
266|	struct ucl_dtor_worklist *wl = (struct ucl_dtor_worklist *) ud;
267|
268|	if (obj == NULL) {
269|		return;
270|	}
271|
272|#ifdef HAVE_ATOMIC_BUILTINS
273|	if (__sync_sub_and_fetch(&obj->ref, 1) == 0) {
274|#else
275|	if (--obj->ref == 0) {
276|#endif
277|		ucl_dtor_worklist_push(wl, obj);
278|	}
279|}
280|
281|/*
282| * Queue every element of an implicit-array chain starting at `obj`. The chain
283| * links are read before each element is unreffed, since unreffing may reuse
284| * them for the worklist.
285| */
286|static inline void
287|ucl_dtor_worklist_unref_chain(struct ucl_dtor_worklist *wl, ucl_object_t *obj)
288|{
289|	ucl_object_t *tmp;
290|
291|	while (obj != NULL) {
292|		tmp = obj->next;
293|		ucl_dtor_worklist_unref(obj, wl);
294|		obj = tmp;
295|	}
296|}
297|
298|/*
299| * Release a whole subtree. `obj` must have already reached zero references;
300| * with `allow_rec` its implicit-array siblings are released as well.
301| */
302|static void
303|ucl_object_free_internal(ucl_object_t *obj, bool allow_rec)
304|{
305|	struct ucl_dtor_worklist wl = {NULL};
306|	ucl_object_t *cur, *sub, *tmp;
307|
308|	if (obj == NULL) {
309|		return;
310|	}
311|
312|	/*
313|	 * The head is dead already, so it goes straight onto the worklist; its
314|	 * siblings still hold a reference each and have to be unreffed properly.
315|	 * Save the link first, pushing overwrites it.
316|	 */
317|	tmp = obj->next;
318|	ucl_dtor_worklist_push(&wl, obj);
319|
320|	if (allow_rec) {
321|		ucl_dtor_worklist_unref_chain(&wl, tmp);
322|	}
323|
324|	while ((cur = ucl_dtor_worklist_pop(&wl)) != NULL) {
325|		if (cur->type == UCL_ARRAY) {
326|			UCL_ARRAY_GET(vec, cur);
327|
328|			if (vec != NULL) {
329|				unsigned int i;
330|
331|				for (i = 0; i < vec->n; i++) {
332|					sub = kv_A(*vec, i);
333|					ucl_dtor_worklist_unref_chain(&wl, sub);
334|				}
335|
336|				kv_destroy(*vec);
337|				UCL_FREE(sizeof(*vec), vec);
338|			}
339|
340|			cur->value.av = NULL;
341|		}
342|		else if (cur->type == UCL_OBJECT) {
343|			if (cur->value.ov != NULL) {
344|				ucl_hash_destroy(cur->value.ov, ucl_dtor_worklist_unref, &wl);
345|			}
346|
347|			cur->value.ov = NULL;
348|		}
349|
350|		ucl_object_dtor_free(cur);
351|	}
352|}
353|
354|/*
355| * Release `obj` along with the objects it directly holds, without descending
356| * into them and without touching reference counts. Only valid for objects
357| * that are known not to be shared - parser trash and the deprecated
358| * ucl_object_free() below.
359| */
360|static void
361|ucl_object_free_shallow(ucl_object_t *obj)
362|{
363|	ucl_object_t *sub, *tmp;
364|
365|	if (obj->type == UCL_ARRAY) {
366|		UCL_ARRAY_GET(vec, obj);
367|
368|		if (vec != NULL) {
369|			unsigned int i;
370|
371|			for (i = 0; i < vec->n; i++) {
372|				sub = kv_A(*vec, i);
373|
374|				while (sub != NULL) {
375|					tmp = sub->next;
376|					ucl_object_dtor_free(sub);
377|					sub = tmp;
378|				}
379|			}
380|
381|			kv_destroy(*vec);
382|			UCL_FREE(sizeof(*vec), vec);
383|		}
384|
385|		obj->value.av = NULL;
386|	}
387|	else if (obj->type == UCL_OBJECT) {
388|		if (obj->value.ov != NULL) {
389|			ucl_hash_destroy(obj->value.ov, ucl_object_dtor_free_ud, NULL);
390|		}
391|
392|		obj->value.ov = NULL;
393|	}
394|
395|	ucl_object_dtor_free(obj);
396|}
397|
398|void ucl_array_detach_elements(ucl_object_t *ar)
399|{
400|	if (ar == NULL || ar->type != UCL_ARRAY) {
401|		return;
402|	}
403|
404|	UCL_ARRAY_GET(vec, ar);
405|
406|	if (vec != NULL) {
407|		vec->n = 0;
408|	}
409|
410|	ar->len = 0;
411|}
