413|void ucl_object_free(ucl_object_t *obj)
414|{
415|	/*
416|	 * Deprecated: refcount blind, use ucl_object_unref() instead.
417|	 *
418|	 * Release the whole subtree recursively (via the worklist based
419|	 * ucl_object_free_internal) rather than only the direct children.
420|	 * A shallow free drops the hash tables of nested containers and
421|	 * leaks their entire subtrees, so it must not be used here.
422|	 */
423|	ucl_object_free_internal(obj, true);
424|}
