914|/**
915| * Fetch a url and save results to the memory buffer
916| * @param url url to fetch
917| * @param len length of url
918| * @param buf target buffer
919| * @param buflen target length
920| * @return
921| */
922|bool ucl_fetch_url(const unsigned char *url, unsigned char **buf, size_t *buflen,
923|				   UT_string **err, bool must_exist)
924|{
925|
926|#ifdef HAVE_FETCH_H
927|	struct url *fetch_url;
928|	struct url_stat us;
929|	FILE *in;
930|
931|	fetch_url = fetchParseURL(url);
932|	if (fetch_url == NULL) {
933|		ucl_create_err(err, "invalid URL %s: %s",
934|					   url, strerror(errno));
935|		return false;
936|	}
937|	if ((in = fetchXGet(fetch_url, &us, "")) == NULL) {
938|		if (!must_exist) {
939|			ucl_create_err(err, "cannot fetch URL %s: %s",
940|						   url, strerror(errno));
941|		}
942|		fetchFreeURL(fetch_url);
943|		return false;
944|	}
945|
946|	*buflen = us.size;
947|	*buf = UCL_ALLOC(*buflen);
948|	if (*buf == NULL) {
949|		ucl_create_err(err, "cannot allocate buffer for URL %s: %s",
950|					   url, strerror(errno));
951|		fclose(in);
952|		fetchFreeURL(fetch_url);
953|		return false;
954|	}
955|
956|	if (fread(*buf, *buflen, 1, in) != 1) {
957|		ucl_create_err(err, "cannot read URL %s: %s",
958|					   url, strerror(errno));
959|		fclose(in);
960|		fetchFreeURL(fetch_url);
961|		return false;
962|	}
963|
964|	fetchFreeURL(fetch_url);
965|	return true;
966|#elif defined(CURL_FOUND)
967|	CURL *curl;
968|	int r;
969|	struct ucl_curl_cbdata cbdata;
970|
971|	curl = curl_easy_init();
972|	if (curl == NULL) {
973|		ucl_create_err(err, "CURL interface is broken");
974|		return false;
975|	}
976|	if ((r = curl_easy_setopt(curl, CURLOPT_URL, url)) != CURLE_OK) {
977|		ucl_create_err(err, "invalid URL %s: %s",
978|					   url, curl_easy_strerror(r));
979|		curl_easy_cleanup(curl);
980|		return false;
981|	}
982|	curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, ucl_curl_write_callback);
983|	cbdata.buf = NULL;
984|	cbdata.buflen = 0;
985|	curl_easy_setopt(curl, CURLOPT_WRITEDATA, &cbdata);
986|
987|	if ((r = curl_easy_perform(curl)) != CURLE_OK) {
988|		if (!must_exist) {
989|			ucl_create_err(err, "error fetching URL %s: %s",
990|						   url, curl_easy_strerror(r));
991|		}
992|		curl_easy_cleanup(curl);
993|		if (cbdata.buf) {
994|			UCL_FREE(cbdata.buflen, cbdata.buf);
995|		}
996|		return false;
997|	}
998|	*buf = cbdata.buf;
999|	*buflen = cbdata.buflen;
1000|
1001|	curl_easy_cleanup(curl);
1002|
1003|	return true;
1004|#else
1005|	ucl_create_err(err, "URL support is disabled");
1006|	return false;
1007|#endif
