1010|/**
1011| * Fetch a file and save results to the memory buffer
1012| * @param filename filename to fetch
1013| * @param len length of filename
1014| * @param buf target buffer
1015| * @param buflen target length
1016| * @return
1017| */
1018|bool ucl_fetch_file(const unsigned char *filename, unsigned char **buf, size_t *buflen,
1019|					UT_string **err, bool must_exist)
1020|{
1021|	int fd;
1022|	struct stat st;
1023|	if ((fd = open(filename, O_RDONLY)) == -1) {
1024|		ucl_create_err(err, "cannot open file %s: %s",
1025|					   filename, strerror(errno));
1026|		return false;
1027|	}
1028|
1029|	if (fstat(fd, &st) == -1) {
1030|		if (must_exist || errno == EPERM) {
1031|			ucl_create_err(err, "cannot stat file %s: %s",
1032|						   filename, strerror(errno));
1033|		}
1034|		close(fd);
1035|
1036|		return false;
1037|	}
1038|	if (!S_ISREG(st.st_mode)) {
1039|		if (must_exist) {
1040|			ucl_create_err(err, "file %s is not a regular file", filename);
1041|		}
1042|		close(fd);
1043|
1044|		return false;
1045|	}
1046|
1047|	if (st.st_size == 0) {
1048|		/* Do not map empty files */
1049|		*buf = NULL;
1050|		*buflen = 0;
1051|	}
1052|	else {
1053|		if ((*buf = ucl_mmap(NULL, st.st_size, PROT_READ, MAP_SHARED, fd, 0)) == MAP_FAILED) {
1054|			close(fd);
1055|			ucl_create_err(err, "cannot mmap file %s: %s",
1056|						   filename, strerror(errno));
1057|			*buf = NULL;
1058|
1059|			return false;
1060|		}
1061|		*buflen = st.st_size;
1062|	}
1063|
1064|	close(fd);
1065|
1066|	return true;
