1070|#if (defined(HAVE_OPENSSL) && OPENSSL_VERSION_NUMBER >= 0x10000000L)
1071|static inline bool
1072|ucl_sig_check(const unsigned char *data, size_t datalen,
1073|			  const unsigned char *sig, size_t siglen, struct ucl_parser *parser)
1074|{
1075|	struct ucl_pubkey *key;
1076|	char dig[EVP_MAX_MD_SIZE];
1077|	unsigned int diglen;
1078|	EVP_PKEY_CTX *key_ctx;
1079|	EVP_MD_CTX *sign_ctx = NULL;
1080|
1081|	sign_ctx = EVP_MD_CTX_create();
1082|
1083|	LL_FOREACH(parser->keys, key)
1084|	{
1085|		key_ctx = EVP_PKEY_CTX_new(key->key, NULL);
1086|		if (key_ctx != NULL) {
1087|			if (EVP_PKEY_verify_init(key_ctx) <= 0) {
1088|				EVP_PKEY_CTX_free(key_ctx);
1089|				continue;
1090|			}
1091|			if (EVP_PKEY_CTX_set_rsa_padding(key_ctx, RSA_PKCS1_PADDING) <= 0) {
1092|				EVP_PKEY_CTX_free(key_ctx);
1093|				continue;
1094|			}
1095|			if (EVP_PKEY_CTX_set_signature_md(key_ctx, EVP_sha256()) <= 0) {
1096|				EVP_PKEY_CTX_free(key_ctx);
1097|				continue;
1098|			}
1099|			EVP_DigestInit(sign_ctx, EVP_sha256());
1100|			EVP_DigestUpdate(sign_ctx, data, datalen);
1101|			EVP_DigestFinal(sign_ctx, dig, &diglen);
1102|
1103|			if (EVP_PKEY_verify(key_ctx, sig, siglen, dig, diglen) == 1) {
1104|				EVP_MD_CTX_destroy(sign_ctx);
1105|				EVP_PKEY_CTX_free(key_ctx);
1106|				return true;
1107|			}
1108|
1109|			EVP_PKEY_CTX_free(key_ctx);
1110|		}
1111|	}
1112|
1113|	EVP_MD_CTX_destroy(sign_ctx);
1114|
1115|	return false;
1116|}
1117|#endif
