3784|static ucl_object_t *
3785|ucl_object_copy_internal(const ucl_object_t *other, bool allow_array)
3786|{
3787|
3788|	ucl_object_t *new;
3789|	ucl_object_iter_t it = NULL;
3790|	const ucl_object_t *cur;
3791|	size_t sz = sizeof(*new);
3792|
3793|	if (other->type == UCL_USERDATA) {
3794|		sz = sizeof(struct ucl_object_userdata);
3795|	}
3796|	new = UCL_ALLOC(sz);
3797|
3798|	if (new != NULL) {
3799|		memcpy(new, other, sz);
3800|		if (other->flags & UCL_OBJECT_EPHEMERAL) {
3801|			/* Copied object is always non ephemeral */
3802|			new->flags &= ~UCL_OBJECT_EPHEMERAL;
3803|		}
3804|		new->ref = 1;
3805|		/* Unlink from others */
3806|		new->next = NULL;
3807|		new->prev = new;
3808|
3809|		/* deep copy of values stored */
3810|		if (other->trash_stack[UCL_TRASH_KEY] != NULL) {
3811|			new->trash_stack[UCL_TRASH_KEY] = NULL;
3812|			if (other->key == (const char *) other->trash_stack[UCL_TRASH_KEY]) {
3813|				new->trash_stack[UCL_TRASH_KEY] = UCL_ALLOC(other->keylen + 1);
3814|				memcpy(new->trash_stack[UCL_TRASH_KEY], other->trash_stack[UCL_TRASH_KEY], other->keylen);
3815|				new->trash_stack[UCL_TRASH_KEY][other->keylen] = '\0';
3816|				new->key = new->trash_stack[UCL_TRASH_KEY];
3817|			}
3818|		}
3819|		if (other->trash_stack[UCL_TRASH_VALUE] != NULL) {
3820|			new->trash_stack[UCL_TRASH_VALUE] =
3821|				UCL_STRDUP(other->trash_stack[UCL_TRASH_VALUE]);
3822|			if (new->type == UCL_STRING) {
3823|				new->value.sv = new->trash_stack[UCL_TRASH_VALUE];
3824|			}
3825|		}
3826|
3827|		if (other->type == UCL_ARRAY || other->type == UCL_OBJECT) {
3828|			/* reset old value and length since we will re-add elements below */
3829|			memset(&new->value, 0, sizeof(new->value));
3830|			new->len = 0;
3831|
3832|			while ((cur = ucl_object_iterate(other, &it, true)) != NULL) {
3833|				if (other->type == UCL_ARRAY) {
3834|					ucl_array_append(new, ucl_object_copy_internal(cur, false));
3835|				}
3836|				else {
3837|					ucl_object_t *cp = ucl_object_copy_internal(cur, true);
3838|					if (cp != NULL) {
3839|						ucl_object_insert_key(new, cp, cp->key, cp->keylen,
3840|											  false);
3841|					}
3842|				}
3843|			}
3844|		}
3845|		else if (allow_array && other->next != NULL) {
3846|			LL_FOREACH(other->next, cur)
3847|			{
3848|				ucl_object_t *cp = ucl_object_copy_internal(cur, false);
3849|				if (cp != NULL) {
3850|					DL_APPEND(new, cp);
3851|				}
3852|			}
3853|		}
3854|	}
3855|
3856|	return new;
3857|}
