3879|int ucl_object_compare(const ucl_object_t *o1, const ucl_object_t *o2)
3880|{
3881|	const ucl_object_t *it1, *it2;
3882|	ucl_object_iter_t iter = NULL;
3883|	int ret = 0;
3884|
3885|	if (o1->type != o2->type) {
3886|		return (o1->type) - (o2->type);
3887|	}
3888|
3889|	switch (o1->type) {
3890|	case UCL_STRING:
3891|		if (o1->len == o2->len && o1->len > 0) {
3892|			ret = strcmp(ucl_object_tostring(o1), ucl_object_tostring(o2));
3893|		}
3894|		else {
3895|			ret = o1->len - o2->len;
3896|		}
3897|		break;
3898|	case UCL_FLOAT:
3899|	case UCL_INT:
3900|	case UCL_TIME:
3901|		ret = ucl_object_todouble(o1) - ucl_object_todouble(o2);
3902|		break;
3903|	case UCL_BOOLEAN:
3904|		ret = ucl_object_toboolean(o1) - ucl_object_toboolean(o2);
3905|		break;
3906|	case UCL_ARRAY:
3907|		if (o1->len == o2->len && o1->len > 0) {
3908|			UCL_ARRAY_GET(vec1, o1);
3909|			UCL_ARRAY_GET(vec2, o2);
3910|			unsigned i;
3911|
3912|			/* Compare all elements in both arrays */
3913|			for (i = 0; i < vec1->n; i++) {
3914|				it1 = kv_A(*vec1, i);
3915|				it2 = kv_A(*vec2, i);
3916|
3917|				if (it1 == NULL && it2 != NULL) {
3918|					return -1;
3919|				}
3920|				else if (it2 == NULL && it1 != NULL) {
3921|					return 1;
3922|				}
3923|				else if (it1 != NULL && it2 != NULL) {
3924|					ret = ucl_object_compare(it1, it2);
3925|					if (ret != 0) {
3926|						break;
3927|					}
3928|				}
3929|			}
3930|		}
3931|		else {
3932|			ret = o1->len - o2->len;
3933|		}
3934|		break;
3935|	case UCL_OBJECT:
3936|		if (o1->len == o2->len && o1->len > 0) {
3937|			while ((it1 = ucl_object_iterate(o1, &iter, true)) != NULL) {
3938|				it2 = ucl_object_lookup(o2, ucl_object_key(it1));
3939|				if (it2 == NULL) {
3940|					ret = 1;
3941|					break;
3942|				}
3943|				ret = ucl_object_compare(it1, it2);
3944|				if (ret != 0) {
3945|					break;
3946|				}
3947|			}
3948|		}
3949|		else {
3950|			ret = o1->len - o2->len;
3951|		}
3952|		break;
3953|	default:
3954|		ret = 0;
3955|		break;
3956|	}
3957|
3958|	return ret;
3959|}
