238|/**
239| * Return multiplier for a character
240| * @param c multiplier character
241| * @param is_bytes if true use 1024 multiplier
242| * @return multiplier
243| */
244|static inline unsigned long
245|ucl_lex_num_multiplier(const unsigned char c, bool is_bytes)
246|{
247|	const struct {
248|		char c;
249|		long mult_normal;
250|		long mult_bytes;
251|	} multipliers[] = {
252|		{'m', 1000 * 1000, 1024 * 1024},
253|		{'k', 1000, 1024},
254|		{'g', 1000 * 1000 * 1000, 1024 * 1024 * 1024}};
255|	int i;
256|
257|	for (i = 0; i < 3; i++) {
258|		if (tolower(c) == multipliers[i].c) {
259|			if (is_bytes) {
260|				return multipliers[i].mult_bytes;
261|			}
262|			return multipliers[i].mult_normal;
263|		}
264|	}
265|
266|	return 1;
