382|/**
383| * Check for a variable in a given string
384| * @param parser
385| * @param ptr
386| * @param remain
387| * @param out_len
388| * @param vars_found
389| * @return
390| */
391|static const char *
392|ucl_check_variable(struct ucl_parser *parser, const char *ptr,
393|				   size_t remain, size_t *out_len, bool *vars_found)
394|{
395|	const char *p, *end, *ret = ptr;
396|	bool found = false;
397|
398|	if (*ptr == '{') {
399|		/* We need to match the variable enclosed in braces */
400|		p = ptr + 1;
401|		end = ptr + remain;
402|		while (p < end) {
403|			if (*p == '}') {
404|				ret = ucl_check_variable_safe(parser, ptr + 1, p - ptr - 1,
405|											  out_len, true, &found);
406|				if (found) {
407|					/* {} must be excluded actually */
408|					ret++;
409|					if (!*vars_found) {
410|						*vars_found = true;
411|					}
412|				}
413|				else {
414|					*out_len += 2;
415|				}
416|				break;
417|			}
418|			p++;
419|		}
420|		if (p == end) {
421|			(*out_len)++;
422|		}
423|	}
424|	else if (*ptr != '$') {
425|		/* Not count escaped dollar sign */
426|		ret = ucl_check_variable_safe(parser, ptr, remain, out_len, false, &found);
427|		if (found && !*vars_found) {
428|			*vars_found = true;
429|		}
430|		if (!found) {
431|			(*out_len)++;
432|		}
433|	}
434|	else {
435|		ret++;
436|		(*out_len)++;
437|	}
438|
439|	return ret;
440|}
441|
442|/**
443| * Expand a single variable
444| * @param parser
445| * @param ptr
446| * @param in_len
447| * @param dest
448| * @param out_len
449| * @return
450| */
451|static const char *
452|ucl_expand_single_variable(struct ucl_parser *parser, const char *ptr,
453|						   size_t in_len, unsigned char **dest, size_t out_len)
454|{
455|	unsigned char *d = *dest, *dst;
456|	const char *p = ptr + 1, *ret;
457|	struct ucl_variable *var;
458|	size_t dstlen;
459|	bool need_free = false;
460|	bool found = false;
461|	bool strict = false;
462|
463|	ret = ptr + 1;
464|	/* For the $ sign */
465|	in_len--;
466|
467|	if (*p == '$') {
468|		*d++ = *p++;
469|		*dest = d;
470|		return p;
471|	}
472|	else if (*p == '{') {
473|		p++;
474|		in_len--;
475|		strict = true;
476|		ret += 2;
477|	}
478|
479|	LL_FOREACH(parser->variables, var)
480|	{
481|		if (out_len >= var->value_len && in_len >= (var->var_len + (strict ? 1 : 0))) {
482|			if (memcmp(p, var->var, var->var_len) == 0) {
483|				if (!strict || p[var->var_len] == '}') {
484|					memcpy(d, var->value, var->value_len);
485|					ret += var->var_len;
486|					d += var->value_len;
487|					found = true;
488|					break;
489|				}
490|			}
491|		}
492|	}
493|
494|	if (!found) {
495|		if (strict && parser->var_handler != NULL) {
496|			dstlen = out_len;
497|
498|			if (parser->var_handler(p, in_len, &dst, &dstlen, &need_free,
499|									parser->var_data)) {
500|				if (dstlen > out_len) {
501|					/* We do not have enough space! */
502|					if (need_free) {
503|						free(dst);
504|					}
505|				}
506|				else {
507|					memcpy(d, dst, dstlen);
508|					ret += in_len;
509|					d += dstlen;
510|					found = true;
511|
512|					if (need_free) {
513|						free(dst);
514|					}
515|				}
516|			}
517|		}
518|
519|		/* Leave variable as is, in this case we use dest */
520|		if (!found) {
521|			if (strict && out_len >= 2) {
522|				/* Copy '${' */
523|				memcpy(d, ptr, 2);
524|				d += 2;
525|				ret--;
526|			}
527|			else {
528|				memcpy(d, ptr, 1);
529|				d++;
530|			}
531|		}
532|	}
533|
534|	*dest = d;
535|	return ret;
536|}
537|
538|/**
539| * Expand variables in string
540| * @param parser
541| * @param dst
542| * @param src
543| * @param in_len
544| * @return
545| */
546|static ssize_t
547|ucl_expand_variable(struct ucl_parser *parser, unsigned char **dst,
548|					const char *src, size_t in_len)
549|{
550|	const char *p, *end = src + in_len;
551|	unsigned char *d, *d_end;
552|	size_t out_len = 0;
553|	bool vars_found = false;
554|
555|	if (parser->flags & UCL_PARSER_DISABLE_MACRO) {
556|		*dst = NULL;
557|		return in_len;
558|	}
559|
560|	p = src;
561|	while (p != end) {
562|		if (*p == '$' && p + 1 != end) {
563|			p = ucl_check_variable(parser, p + 1, end - p - 1, &out_len, &vars_found);
564|		}
565|		else {
566|			p++;
567|			out_len++;
568|		}
569|	}
570|
571|	if (!vars_found) {
572|		/* Trivial case */
573|		*dst = NULL;
574|		return in_len;
575|	}
576|
577|	*dst = UCL_ALLOC(out_len + 1);
578|	if (*dst == NULL) {
579|		return in_len;
580|	}
581|
582|	d = *dst;
583|	d_end = d + out_len;
584|	p = src;
585|	while (p != end && d != d_end) {
586|		if (*p == '$' && p + 1 != end) {
587|			p = ucl_expand_single_variable(parser, p, end - p, &d, d_end - d);
588|		}
589|		else {
590|			*d++ = *p++;
591|		}
592|	}
593|
594|	*d = '\0';
595|
596|	return out_len;
597|}
