743|/**
744| * Create and append an object at the specified level
745| * @param parser
746| * @param is_array
747| * @param level
748| * @return
749| */
750|static inline ucl_object_t *
751|ucl_parser_add_container(ucl_object_t *obj, struct ucl_parser *parser,
752|						 bool is_array, uint32_t level, bool has_obrace)
753|{
754|	struct ucl_stack *st;
755|	ucl_object_t *nobj;
756|
757|	/*
758|	 * `level` below is the UCL dotted-key nesting level, which says nothing
759|	 * about how deep the containers actually are; the stack depth does, and
760|	 * that is what every recursive walk over the resulting tree (emitting,
761|	 * copying, and destruction itself) is proportional to. Checked before
762|	 * anything is allocated.
763|	 */
764|	if (parser->limits.max_depth > 0 &&
