1536|/**
1537| * Parse a key in an object
1538| * @param parser
1539| * @param chunk
1540| * @param next_key
1541| * @param end_of_object
1542| * @return true if a key has been parsed
1543| */
1544|static bool
1545|ucl_parse_key(struct ucl_parser *parser, struct ucl_chunk *chunk,
1546|			  bool *next_key, bool *end_of_object, bool *got_content)
1547|{
1548|	const unsigned char *p, *c = NULL, *end, *t;
1549|	const char *key = NULL;
1550|	bool got_quote = false, got_eq = false, got_semicolon = false,
1551|		 need_unescape = false, ucl_escape = false, var_expand = false,
