1555|
1556|	p = chunk->pos;
1557|
1558|	if (p >= chunk->end) {
1559|		ucl_set_err(parser, UCL_ESYNTAX,
1560|					"unexpected end of input while parsing key",
1561|					&parser->err);
1562|		*end_of_object = true;
1563|		return true;
1564|	}
1565|
1566|	if (*p == '.' && !(parser->flags & UCL_PARSER_DISABLE_MACRO)) {
1567|		ucl_chunk_skipc(chunk, p);
1568|		parser->prev_state = parser->state;
1569|		parser->state = UCL_STATE_MACRO_NAME;
1570|		*end_of_object = false;
1571|		return true;
1572|	}
1573|	while (p < chunk->end) {
1574|		/*
1575|		 * A key must start with alpha, number, '/' or '_' and end with space character
1576|		 */
