1621|				if (ucl_test_character(*p, UCL_CHARACTER_KEY)) {
1622|					*got_content = true;
1623|					ucl_chunk_skipc(chunk, p);
1624|				}
1625|				else if (ucl_test_character(*p, UCL_CHARACTER_KEY_SEP)) {
1626|					end = p;
1627|					break;
1628|				}
1629|				else {
1630|					ucl_set_err(parser, UCL_ESYNTAX, "invalid character in a key",
1631|								&parser->err);
1632|					return false;
1633|				}
1634|			}
1635|			else {
1636|				/* We need to parse json like quoted string */
