1670|			}
1671|		}
1672|		else if (*p == ':') {
1673|			if (!got_eq && !got_semicolon) {
1674|				ucl_chunk_skipc(chunk, p);
1675|				got_semicolon = true;
1676|			}
1677|			else {
1678|				ucl_set_err(parser, UCL_ESYNTAX, "unexpected ':' character",
1679|							&parser->err);
1680|				return false;
1681|			}
1682|		}
1683|		else if (chunk->remain >= 2 && ucl_lex_is_comment(p[0], p[1])) {
1684|			/* Check for comment */
1685|			if (!ucl_skip_comments(parser)) {
1686|				return false;
1687|			}
1688|			p = chunk->pos;
1689|		}
1690|		else {
1691|			/* Start value */
1692|			break;
1693|		}
1694|	}
1695|
1696|	if (p >= chunk->end && got_content) {
1697|		ucl_set_err(parser, UCL_ESYNTAX, "unfinished key", &parser->err);
1698|		return false;
1699|	}
1700|
1701|	got_sep = got_semicolon || got_eq;
1702|
1703|	if (!got_sep) {
1704|		/*
1705|		 * Maybe we have more keys nested, so search for termination character.
1706|		 * Possible choices:
1707|		 * 1) key1 key2 ... keyN [:=] value <- we treat that as error
1708|		 * 2) key1 ... keyN {} or [] <- we treat that as nested objects
1709|		 * 3) key1 value[;,\n] <- we treat that as linear object
1710|		 */
1711|		t = p;
1712|		*next_key = false;
1713|		while (ucl_test_character(*t, UCL_CHARACTER_WHITESPACE)) {
1714|			t++;
1715|		}
