1721|				}
1722|				else if (*t == '{' || *t == '[') {
1723|					*next_key = true;
1724|					break;
1725|				}
1726|				t++;
1727|			}
1728|		}
1729|	}
1730|
1731|	/* Create a new object */
1732|	nobj = ucl_object_new_full(UCL_NULL, parser->chunks->priority);
1733|	if (nobj == NULL) {
1734|		return false;
1735|	}
1736|
1737|	if (!ucl_parser_account_node(parser)) {
1738|		ucl_object_unref(nobj);
1739|		return false;
1740|	}
1741|
1742|	keylen = ucl_copy_or_store_ptr(parser, c, &nobj->trash_stack[UCL_TRASH_KEY],
1743|								   &key, end - c, parser->limits.max_key_length,
1744|								   need_unescape, parser->flags & UCL_PARSER_KEY_LOWERCASE,
1745|								   false, false);
