1771|/**
1772| * Parse a cl string
1773| * @param parser
1774| * @param chunk
1775| * @param var_expand
1776| * @param need_unescape
1777| * @return true if a key has been parsed
1778| */
1779|static bool
1780|ucl_parse_string_value(struct ucl_parser *parser,
1781|					   struct ucl_chunk *chunk, bool *var_expand, bool *need_unescape)
1782|{
1783|	const unsigned char *p;
1784|	enum {
1785|		UCL_BRACE_ROUND = 0,
1786|		UCL_BRACE_SQUARE,
1787|		UCL_BRACE_FIGURE
1788|	};
1789|	int braces[3][2] = {{0, 0}, {0, 0}, {0, 0}};
1790|
1791|	p = chunk->pos;
1792|
1793|	while (p < chunk->end) {
1794|
1795|		/* Skip pairs of figure braces */
1796|		if (*p == '{') {
1797|			braces[UCL_BRACE_FIGURE][0]++;
1798|		}
1799|		else if (*p == '}') {
1800|			braces[UCL_BRACE_FIGURE][1]++;
1801|			if (braces[UCL_BRACE_FIGURE][1] <= braces[UCL_BRACE_FIGURE][0]) {
1802|				/* This is not a termination symbol, continue */
1803|				ucl_chunk_skipc(chunk, p);
1804|				continue;
1805|			}
1806|		}
1807|		/* Skip pairs of square braces */
1808|		else if (*p == '[') {
1809|			braces[UCL_BRACE_SQUARE][0]++;
1810|		}
1811|		else if (*p == ']') {
1812|			braces[UCL_BRACE_SQUARE][1]++;
1813|			if (braces[UCL_BRACE_SQUARE][1] <= braces[UCL_BRACE_SQUARE][0]) {
1814|				/* This is not a termination symbol, continue */
1815|				ucl_chunk_skipc(chunk, p);
1816|				continue;
1817|			}
1818|		}
1819|		else if (*p == '$') {
1820|			*var_expand = true;
1821|		}
1822|		else if (*p == '\\') {
1823|			*need_unescape = true;
1824|			ucl_chunk_skipc(chunk, p);
1825|			if (p < chunk->end) {
1826|				ucl_chunk_skipc(chunk, p);
1827|			}
1828|			continue;
1829|		}
1830|
1831|		if (ucl_lex_is_atom_end(*p) || (chunk->remain >= 2 && ucl_lex_is_comment(p[0], p[1]))) {
1832|			break;
1833|		}
1834|		ucl_chunk_skipc(chunk, p);
1835|	}
1836|
1837|	return true;
1838|}
