1934|/**
1935| * Handle value data
1936| * @param parser
1937| * @param chunk
1938| * @return
1939| */
1940|static bool
1941|ucl_parse_value(struct ucl_parser *parser, struct ucl_chunk *chunk)
1942|{
1943|	const unsigned char *p, *c;
1944|	ucl_object_t *obj = NULL;
1945|	unsigned int stripped_spaces;
1946|	ssize_t str_len;
1947|	bool need_unescape = false, ucl_escape = false, var_expand = false;
