3247|				size_t nlen = 0;
3248|
3249|				if (!special_handler->handler(parser, data, len, &ndata, &nlen,
3250|											  special_handler->user_data)) {
3251|					UCL_FREE(sizeof(struct ucl_chunk), chunk);
3252|					ucl_create_err(&parser->err, "call for external handler failed");
3253|
3254|					return false;
3255|				}
3256|
3257|				struct ucl_parser_special_handler_chain *nchain;
3258|				nchain = UCL_ALLOC(sizeof(*nchain));
3259|				nchain->begin = ndata;
3260|				nchain->len = nlen;
3261|				nchain->special_handler = special_handler;
3262|
3263|				/* Free order is reversed */
3264|				LL_PREPEND(chunk->special_handlers, nchain);
3265|
3266|				data = ndata;
3267|				len = nlen;
3268|			}
3269|		}
3270|
3271|		if (parse_type == UCL_PARSE_AUTO && len > 0) {
3272|			/* We need to detect parse type by the first symbol */
3273|			if (len >= 3 && data[0] == 0xd9 && data[1] == 0xd9 &&
3274|				data[2] == 0xf7) {
3275|				/*
3276|				 * The self-described cbor tag, 55799. Cbor and msgpack are
3277|				 * otherwise indistinguishable from their first byte - both
3278|				 * spend 0x80 to 0xbf on short containers and strings - so
3279|				 * this prefix is the only thing that tells them apart, and
3280|				 * cbor without it has to be requested explicitly.
3281|				 */
3282|				parse_type = UCL_PARSE_CBOR;
3283|			}
3284|			else if ((*data & 0x80) == 0x80) {
3285|				parse_type = UCL_PARSE_MSGPACK;
3286|			}
3287|			else if (*data == '(') {
3288|				parse_type = UCL_PARSE_CSEXP;
3289|			}
3290|			else {
3291|				parse_type = UCL_PARSE_UCL;
3292|			}
3293|		}
3294|
3295|		chunk->begin = data;
3296|		chunk->remain = len;
3297|		chunk->pos = chunk->begin;
3298|		chunk->end = chunk->begin + len;
3299|		chunk->line = 1;
3300|		chunk->column = 0;
3301|		chunk->priority = priority;
3302|		chunk->strategy = strat;
3303|		chunk->parse_type = parse_type;
3304|
3305|		if (parser->cur_file) {
3306|			chunk->fname = UCL_STRDUP(parser->cur_file);
3307|		}
3308|
3309|		LL_PREPEND(parser->chunks, chunk);
3310|		parser->recursion++;
3311|
3312|		if (parser->recursion > UCL_MAX_RECURSION) {
3313|			ucl_create_err(&parser->err, "maximum include nesting limit is reached: %d",
3314|						   parser->recursion);
3315|			return false;
3316|		}
3317|
3318|		if (len > 0) {
3319|			/* Need to parse something */
3320|			switch (parse_type) {
3321|			default:
3322|			case UCL_PARSE_UCL:
3323|				return ucl_state_machine(parser);
3324|			case UCL_PARSE_MSGPACK:
3325|				return ucl_parse_msgpack(parser);
3326|			case UCL_PARSE_CBOR:
3327|				return ucl_parse_cbor(parser);
3328|			case UCL_PARSE_CSEXP:
3329|				return ucl_parse_csexp(parser);
3330|			}
3331|		}
3332|		else {
3333|			/* Just add empty chunk and go forward */
3334|			if (parser->top_obj == NULL) {
3335|				/*
3336|				 * In case of empty object, create one to indicate that we've
3337|				 * read something
3338|				 */
3339|				parser->top_obj = ucl_object_new_full(UCL_OBJECT, priority);
3340|			}
3341|
3342|			return true;
3343|		}
3344|	}
3345|
3346|	ucl_create_err(&parser->err, "a parser is in an invalid state");
3347|
3348|	return false;
3349|}
