41|/**
42| * Move up to len characters
43| * @param parser
44| * @param begin
45| * @param len
46| * @return new position in chunk
47| */
48|#define ucl_chunk_skipc(chunk, p) \
49|	do {                          \
50|		if (p == chunk->end) {    \
51|			break;                \
52|		}                         \
53|		if (*(p) == '\n') {       \
54|			(chunk)->line++;      \
55|			(chunk)->column = 0;  \
56|		}                         \
57|		else                      \
58|			(chunk)->column++;    \
59|		(p++);                    \
60|		(chunk)->pos++;           \
61|		(chunk)->remain--;        \
62|	} while (0)
