323|/**
324| * Check variable found
325| * @param parser
326| * @param ptr
327| * @param remain
328| * @param out_len
329| * @param strict
330| * @param found
331| * @return
332| */
333|static inline const char *
334|ucl_check_variable_safe(struct ucl_parser *parser, const char *ptr, size_t remain,
335|						size_t *out_len, bool strict, bool *found)
336|{
337|	struct ucl_variable *var;
338|	unsigned char *dst;
339|	size_t dstlen;
340|	bool need_free = false;
341|
342|	LL_FOREACH(parser->variables, var)
343|	{
344|		if (strict) {
345|			if (remain == var->var_len) {
346|				if (memcmp(ptr, var->var, var->var_len) == 0) {
347|					*out_len += var->value_len;
348|					*found = true;
349|					return (ptr + var->var_len);
350|				}
351|			}
352|		}
353|		else {
354|			if (remain >= var->var_len) {
355|				if (memcmp(ptr, var->var, var->var_len) == 0) {
356|					*out_len += var->value_len;
357|					*found = true;
358|					return (ptr + var->var_len);
359|				}
360|			}
361|		}
362|	}
363|
364|	/* XXX: can only handle ${VAR} */
365|	if (!(*found) && parser->var_handler != NULL && strict) {
366|		/* Call generic handler */
367|		if (parser->var_handler(ptr, remain, &dst, &dstlen, &need_free,
368|								parser->var_data)) {
369|			*found = true;
370|			*out_len = dstlen;
371|
372|			if (need_free) {
373|				free(dst);
374|			}
375|			return (ptr + remain);
376|		}
377|	}
378|
379|	return ptr;
380|}
