538|/**
539| * Expand variables in string
540| * @param parser
541| * @param dst
542| * @param src
543| * @param in_len
544| * @return
545| */
546|static ssize_t
547|ucl_expand_variable(struct ucl_parser *parser, unsigned char **dst,
548|					const char *src, size_t in_len)
549|{
550|	const char *p, *end = src + in_len;
551|	unsigned char *d, *d_end;
552|	size_t out_len = 0;
553|	bool vars_found = false;
554|
555|	if (parser->flags & UCL_PARSER_DISABLE_MACRO) {
556|		*dst = NULL;
557|		return in_len;
558|	}
559|
560|	p = src;
561|	while (p != end) {
562|		if (*p == '$' && p + 1 != end) {
563|			p = ucl_check_variable(parser, p + 1, end - p - 1, &out_len, &vars_found);
564|		}
565|		else {
566|			p++;
567|			out_len++;
568|		}
569|	}
570|
571|	if (!vars_found) {
572|		/* Trivial case */
573|		*dst = NULL;
574|		return in_len;
575|	}
576|
577|	*dst = UCL_ALLOC(out_len + 1);
578|	if (*dst == NULL) {
579|		return in_len;
580|	}
581|
582|	d = *dst;
583|	d_end = d + out_len;
584|	p = src;
585|	while (p != end && d != d_end) {
586|		if (*p == '$' && p + 1 != end) {
587|			p = ucl_expand_single_variable(parser, p, end - p, &d, d_end - d);
588|		}
589|		else {
590|			*d++ = *p++;
591|		}
592|	}
593|
594|	*d = '\0';
595|
596|	return out_len;
