805|	}
806|	else {
807|		parser->state = UCL_STATE_VALUE;
808|	}
809|
810|	st = UCL_ALLOC(sizeof(struct ucl_stack));
811|
812|	if (st == NULL) {
813|		goto enomem1;
814|	}
815|
816|	st->obj = nobj;
