896|			p++;
897|		}
898|		else if (!is_hex && (*p == 'x' || *p == 'X')) {
899|			is_hex = true;
900|			allow_double = false;
901|			c = p + 1;
902|			p++;
903|		}
904|		else if (allow_double) {
905|			if (p == c) {
906|				/* Empty digits sequence, not a number */
907|				*pos = start;
908|				return EINVAL;
909|			}
910|			else if (*p == '.') {
911|				if (got_dot) {
912|					/* Double dots, not a number */
