914|					return EINVAL;
915|				}
916|				else {
917|					got_dot = true;
918|					need_double = true;
919|					p++;
920|				}
921|			}
922|			else if (*p == 'e' || *p == 'E') {
923|				if (got_exp) {
924|					/* Double exp, not a number */
