1204|/**
1205| * Parse quoted string with possible escapes
1206| * @param parser
1207| * @param chunk
1208| * @param need_unescape
1209| * @param ucl_escape
1210| * @param var_expand
1211| * @return true if a string has been parsed
1212| */
1213|static bool
1214|ucl_lex_json_string(struct ucl_parser *parser,
1215|					struct ucl_chunk *chunk,
1216|					bool *need_unescape,
1217|					bool *ucl_escape,
1218|					bool *var_expand)
1219|{
1220|	const unsigned char *p = chunk->pos;
1221|	unsigned char c;
1222|	int i;
1223|
1224|	while (p < chunk->end) {
1225|		c = *p;
1226|		if (c < 0x1F) {
1227|			/* Unmasked control character */
1228|			if (c == '\n') {
1229|				ucl_set_err(parser, UCL_ESYNTAX, "unexpected newline",
1230|							&parser->err);
1231|			}
1232|			else {
1233|				ucl_set_err(parser, UCL_ESYNTAX, "unexpected control character",
1234|							&parser->err);
1235|			}
1236|			return false;
1237|		}
1238|		else if (c == '\\') {
1239|			ucl_chunk_skipc(chunk, p);
1240|			if (p >= chunk->end) {
1241|				ucl_set_err(parser, UCL_ESYNTAX, "unfinished escape character",
1242|							&parser->err);
1243|				return false;
1244|			}
1245|			c = *p;
1246|			if (ucl_test_character(c, UCL_CHARACTER_ESCAPE)) {
1247|				if (c == 'u') {
