1252|										&parser->err);
1253|							return false;
1254|						}
1255|						ucl_chunk_skipc(chunk, p);
1256|					}
1257|					if (p >= chunk->end) {
1258|						ucl_set_err(parser, UCL_ESYNTAX,
1259|									"unfinished escape character",
1260|									&parser->err);
1261|						return false;
1262|					}
1263|				}
1264|				else {
1265|					ucl_chunk_skipc(chunk, p);
1266|				}
1267|			}
1268|			*need_unescape = true;
1269|			*ucl_escape = true;
1270|			continue;
1271|		}
1272|		else if (c == '"') {
1273|			ucl_chunk_skipc(chunk, p);
