1407|bool ucl_parser_process_object_element(struct ucl_parser *parser, ucl_object_t *nobj)
1408|{
1409|	ucl_hash_t *container;
1410|	ucl_object_t *tobj = NULL, *cur;
1411|	char errmsg[256];
1412|
1413|	container = parser->stack->obj->value.ov;
1414|
1415|	DL_FOREACH(parser->stack->obj, cur)
1416|	{
1417|		if (cur->type == UCL_OBJECT) {
1418|			tobj = __DECONST(ucl_object_t *, ucl_hash_search_obj(cur->value.ov, nobj));
1419|
1420|			if (tobj != NULL) {
1421|				/*
1422|				 * Check if we have found an object in the same container.
1423|				 * If not, we should probably ignore it as we cannot replace it
1424|				 * effectively and we definitely should not unref it.
1425|				 */
1426|				if (cur->value.ov != container) {
1427|					tobj = NULL;
1428|					continue;
1429|				}
1430|				break;
1431|			}
1432|		}
1433|	}
1434|
1435|
1436|	if (tobj == NULL) {
1437|		container = ucl_hash_insert_object(container, nobj,
1438|										   parser->flags & UCL_PARSER_KEY_LOWERCASE);
1439|		if (container == NULL) {
1440|			return false;
1441|		}
1442|		nobj->prev = nobj;
1443|		nobj->next = NULL;
1444|		parser->stack->obj->len++;
1445|	}
