1447|		unsigned priold = ucl_object_get_priority(tobj),
1448|				 prinew = ucl_object_get_priority(nobj);
1449|		switch (parser->chunks->strategy) {
1450|
1451|		case UCL_DUPLICATE_APPEND:
1452|			/*
1453|			 * The logic here is the following:
1454|			 *
1455|			 * - if we have two objects with the same priority, then we form an
1456|			 * implicit or explicit array
1457|			 * - if a new object has bigger priority, then we overwrite an old one
1458|			 * - if a new object has lower priority, then we ignore it
1459|			 */
1460|			/* Special case for inherited objects */
1461|			if (tobj->flags & UCL_OBJECT_INHERITED) {
1462|				prinew = priold + 1;
1463|			}
1464|
1465|			if (priold == prinew) {
1466|				if (!ucl_parser_append_elt(parser, container, tobj, nobj)) {
1467|					return false;
1468|				}
1469|			}
1470|			else if (priold > prinew) {
1471|				/*
1472|				 * We add this new object to a list of trash objects just to ensure
1473|				 * that it won't come to any real object
1474|				 * XXX: rather inefficient approach
1475|				 */
1476|				DL_APPEND(parser->trash_objs, nobj);
1477|			}
1478|			else {
1479|				ucl_hash_replace(container, tobj, nobj);
1480|				ucl_object_unref(tobj);
1481|			}
1482|
1483|			break;
1484|
1485|		case UCL_DUPLICATE_REWRITE:
1486|			/* We just rewrite old values regardless of priority */
1487|			ucl_hash_replace(container, tobj, nobj);
1488|			ucl_object_unref(tobj);
1489|
1490|			break;
1491|
1492|		case UCL_DUPLICATE_ERROR:
1493|			snprintf(errmsg, sizeof(errmsg),
1494|					 "duplicate element for key '%s' found",
1495|					 nobj->key);
1496|			ucl_set_err(parser, UCL_EMERGE, errmsg, &parser->err);
1497|			return false;
1498|
1499|		case UCL_DUPLICATE_MERGE:
1500|			/*
1501|			 * Here we do have some old object so we just push it on top of objects stack
1502|			 * Check priority and then perform the merge on the remaining objects
1503|			 */
1504|			if (tobj->type == UCL_OBJECT || tobj->type == UCL_ARRAY) {
1505|				ucl_object_unref(nobj);
1506|				nobj = tobj;
1507|			}
1508|			else if (priold == prinew) {
1509|				if (!ucl_parser_append_elt(parser, container, tobj, nobj)) {
1510|					return false;
1511|				}
1512|			}
1513|			else if (priold > prinew) {
1514|				/*
1515|				 * We add this new object to a list of trash objects just to ensure
1516|				 * that it won't come to any real object
1517|				 * XXX: rather inefficient approach
1518|				 */
1519|				DL_APPEND(parser->trash_objs, nobj);
1520|			}
1521|			else {
1522|				ucl_hash_replace(container, tobj, nobj);
1523|				ucl_object_unref(tobj);
1524|			}
1525|			break;
1526|		}
1527|	}
1528|
1529|	parser->stack->obj->value.ov = container;
1530|	parser->cur_obj = nobj;
1531|	ucl_attach_comment(parser, nobj, false);
1532|
1533|	return true;
